
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `audit_logs`;
DROP TABLE IF EXISTS `delivery_note_items`;
DROP TABLE IF EXISTS `delivery_notes`;
DROP TABLE IF EXISTS `movements`;
DROP TABLE IF EXISTS `stock_locations`;
DROP TABLE IF EXISTS `items`;
DROP TABLE IF EXISTS `uoms`;
DROP TABLE IF EXISTS `categories`;
DROP TABLE IF EXISTS `suppliers`;
DROP TABLE IF EXISTS `projects`;
DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `companies`;

CREATE TABLE `companies` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `code` VARCHAR(20) NOT NULL,
  `name` VARCHAR(160) NOT NULL,
  `address` VARCHAR(255) DEFAULT NULL,
  `phone` VARCHAR(50) DEFAULT NULL,
  `email` VARCHAR(120) DEFAULT NULL,
  `trn` VARCHAR(50) DEFAULT NULL,
  `letterhead` VARCHAR(255) DEFAULT NULL,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_company_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(50) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `full_name` VARCHAR(120) NOT NULL,
  `email` VARCHAR(120) DEFAULT NULL,
  `role` ENUM('admin','store_manager','store_keeper') NOT NULL,
  `company_id` INT DEFAULT NULL,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `last_login` DATETIME DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_username` (`username`),
  KEY `idx_users_company` (`company_id`),
  CONSTRAINT `fk_users_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `projects` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `company_id` INT NOT NULL,
  `code` VARCHAR(30) NOT NULL,
  `name` VARCHAR(160) NOT NULL,
  `client_name` VARCHAR(160) DEFAULT NULL,
  `location` VARCHAR(160) DEFAULT NULL,
  `status` ENUM('active','completed','on_hold') NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_project` (`company_id`, `code`),
  KEY `idx_proj_company` (`company_id`),
  CONSTRAINT `fk_projects_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `suppliers` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `company_id` INT NOT NULL,
  `code` VARCHAR(30) NOT NULL,
  `name` VARCHAR(160) NOT NULL,
  `contact_person` VARCHAR(120) DEFAULT NULL,
  `phone` VARCHAR(50) DEFAULT NULL,
  `email` VARCHAR(120) DEFAULT NULL,
  `address` VARCHAR(255) DEFAULT NULL,
  `trn` VARCHAR(50) DEFAULT NULL,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_supplier` (`company_id`, `code`),
  KEY `idx_sup_company` (`company_id`),
  CONSTRAINT `fk_suppliers_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `categories` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(100) NOT NULL,
  `description` VARCHAR(255) DEFAULT NULL,
  UNIQUE KEY `uq_cat_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `uoms` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `code` VARCHAR(20) NOT NULL,
  `name` VARCHAR(60) NOT NULL,
  UNIQUE KEY `uq_uom_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `items` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `company_id` INT NOT NULL,
  `item_code` VARCHAR(40) NOT NULL,
  `item_name` VARCHAR(200) NOT NULL,
  `category_id` INT DEFAULT NULL,
  `uom` VARCHAR(20) NOT NULL,
  `quantity` DECIMAL(18,3) NOT NULL DEFAULT 0,
  `opening_qty` DECIMAL(18,3) NOT NULL DEFAULT 0,
  `reorder_level` DECIMAL(18,3) NOT NULL DEFAULT 0,
  `unit_cost` DECIMAL(18,3) NOT NULL DEFAULT 0,
  `project_id` INT NOT NULL DEFAULT 0,
  `supplier_id` INT DEFAULT NULL,
  `rack_no` VARCHAR(30) DEFAULT NULL,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT NULL,
  UNIQUE KEY `uq_item` (`company_id`, `item_code`),
  KEY `idx_item_company` (`company_id`),
  KEY `idx_item_cat` (`category_id`),
  KEY `idx_item_proj` (`project_id`),
  CONSTRAINT `fk_items_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_items_cat` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `stock_locations` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `item_id` INT NOT NULL,
  `company_id` INT NOT NULL,
  `project_id` INT NOT NULL DEFAULT 0,
  `quantity` DECIMAL(18,3) NOT NULL DEFAULT 0,
  UNIQUE KEY `uq_stock_loc` (`item_id`, `project_id`),
  KEY `idx_sl_item` (`item_id`),
  KEY `idx_sl_proj` (`project_id`),
  CONSTRAINT `fk_sl_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `movements` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `company_id` INT NOT NULL,
  `item_id` INT NOT NULL,
  `movement_type` ENUM('IN','OUT','TRANSFER_OUT','TRANSFER_IN','ADJUST') NOT NULL,
  `quantity` DECIMAL(18,3) NOT NULL,
  `uom` VARCHAR(20) DEFAULT NULL,
  `unit_cost` DECIMAL(18,3) NOT NULL DEFAULT 0,
  `project_id` INT NOT NULL DEFAULT 0,
  `from_project_id` INT NOT NULL DEFAULT 0,
  `to_project_id` INT NOT NULL DEFAULT 0,
  `supplier_id` INT DEFAULT NULL,
  `dn_id` INT DEFAULT NULL,
  `transfer_ref` VARCHAR(40) DEFAULT NULL,
  `reference` VARCHAR(80) DEFAULT NULL,
  `movement_date` DATE NOT NULL,
  `notes` VARCHAR(255) DEFAULT NULL,
  `created_by` INT DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY `idx_mv_item` (`item_id`),
  KEY `idx_mv_company` (`company_id`),
  KEY `idx_mv_date` (`movement_date`),
  KEY `idx_mv_type` (`movement_type`),
  KEY `idx_mv_dn` (`dn_id`),
  CONSTRAINT `fk_mv_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_mv_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `delivery_notes` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `company_id` INT NOT NULL,
  `dn_no` VARCHAR(40) NOT NULL,
  `dn_date` DATE NOT NULL,
  `project_id` INT NOT NULL,
  `from_project_id` INT NOT NULL DEFAULT 0,
  `supplier_id` INT DEFAULT NULL,
  `issued_to` VARCHAR(160) DEFAULT NULL,
  `vehicle_no` VARCHAR(50) DEFAULT NULL,
  `driver_name` VARCHAR(120) DEFAULT NULL,
  `driver_contact` VARCHAR(50) DEFAULT NULL,
  `received_by` VARCHAR(160) DEFAULT NULL,
  `prepared_by` INT DEFAULT NULL,
  `approved_by` INT DEFAULT NULL,
  `status` ENUM('draft','issued','received','cancelled') NOT NULL DEFAULT 'draft',
  `notes` VARCHAR(255) DEFAULT NULL,
  `created_by` INT DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_dn_no` (`company_id`, `dn_no`),
  KEY `idx_dn_company` (`company_id`),
  KEY `idx_dn_project` (`project_id`),
  CONSTRAINT `fk_dn_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `delivery_note_items` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `dn_id` INT NOT NULL,
  `item_id` INT NOT NULL,
  `quantity` DECIMAL(18,3) NOT NULL,
  `uom` VARCHAR(20) DEFAULT NULL,
  `remarks` VARCHAR(255) DEFAULT NULL,
  KEY `idx_dni_dn` (`dn_id`),
  KEY `idx_dni_item` (`item_id`),
  CONSTRAINT `fk_dni_dn` FOREIGN KEY (`dn_id`) REFERENCES `delivery_notes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dni_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `audit_logs` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT DEFAULT NULL,
  `username` VARCHAR(60) DEFAULT NULL,
  `company_id` INT DEFAULT NULL,
  `action` VARCHAR(20) NOT NULL,
  `entity` VARCHAR(60) NOT NULL,
  `entity_id` INT DEFAULT NULL,
  `details` TEXT,
  `ip_address` VARCHAR(60) DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY `idx_al_user` (`user_id`),
  KEY `idx_al_entity` (`entity`),
  KEY `idx_al_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;


